function key(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, "");
}

const PLAYER_STATS_BY_KEY = new Map(
  Object.entries(NFL_PLAYER_STATS_2025).map(([name, row]) => [key(name), { name, ...row }]),
);

export function getNflPlayerStats2025(name) {
  return PLAYER_STATS_BY_KEY.get(key(name)) || null;
}

export function countNflPlayerStats2025ByPosition() {
  return Object.values(NFL_PLAYER_STATS_2025).reduce((acc, row) => {
    acc[row.position] = (acc[row.position] || 0) + 1;
    return acc;
  }, {});
}
